public class VendingStateMachineTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        check("empty machine starts SOLD_OUT", "SOLD_OUT",
                safe(() -> String.valueOf(new VendingStateMachine(0).getState())));
        check("stocked machine starts IDLE", "IDLE",
                safe(() -> String.valueOf(new VendingStateMachine(2).getState())));

        check("coin moves IDLE to HAS_CREDIT", "HAS_CREDIT|50",
                safe(() -> {
                    VendingStateMachine m = new VendingStateMachine(2);
                    m.insertCoin(50);
                    return m.getState() + "|" + m.getCredit();
                }));
        check("odd coin is rejected and credit is untouched", "false|IDLE|0",
                safe(() -> {
                    VendingStateMachine m = new VendingStateMachine(2);
                    boolean ok = m.insertCoin(10);
                    return ok + "|" + m.getState() + "|" + m.getCredit();
                }));
        check("select with too little credit is refused", "false|HAS_CREDIT",
                safe(() -> {
                    VendingStateMachine m = new VendingStateMachine(2);
                    m.insertCoin(50);
                    boolean ok = m.select();
                    return ok + "|" + m.getState();
                }));
        check("dispense before select returns -1", -1,
                safe(() -> new VendingStateMachine(2).dispense()));
        check("full sale returns change and goes back to IDLE", "25|IDLE|1|0",
                safe(() -> {
                    VendingStateMachine m = new VendingStateMachine(2);
                    m.insertCoin(100);
                    m.insertCoin(25);
                    m.select();
                    int change = m.dispense();
                    return change + "|" + m.getState() + "|" + m.getStock() + "|" + m.getCredit();
                }));
        check("last item leaves the machine SOLD_OUT", "SOLD_OUT",
                safe(() -> {
                    VendingStateMachine m = new VendingStateMachine(1);
                    m.insertCoin(100);
                    m.select();
                    m.dispense();
                    return String.valueOf(m.getState());
                }));
        check("coins are refused while DISPENSING", "false|100",
                safe(() -> {
                    VendingStateMachine m = new VendingStateMachine(2);
                    m.insertCoin(100);
                    m.select();
                    boolean ok = m.insertCoin(25);
                    return ok + "|" + m.getCredit();
                }));
        check("refund returns the credit and resets to IDLE", "75|IDLE|0",
                safe(() -> {
                    VendingStateMachine m = new VendingStateMachine(2);
                    m.insertCoin(50);
                    m.insertCoin(25);
                    int back = m.refund();
                    return back + "|" + m.getState() + "|" + m.getCredit();
                }));
        check("refund from IDLE returns 0", 0,
                safe(() -> new VendingStateMachine(2).refund()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

