enum VendState {
    IDLE, HAS_CREDIT, DISPENSING, SOLD_OUT
}

public class VendingStateMachine {

    public static final int PRICE = 100;

    private VendState state;
    private int credit;
    private int stock;

    public VendingStateMachine(int stock) {
        this.stock = stock;
        this.credit = 0;
        this.state = stock == 0 ? VendState.SOLD_OUT : VendState.IDLE;
    }

    public VendState getState() {
        return state;
    }

    public int getCredit() {
        return credit;
    }

    public int getStock() {
        return stock;
    }

    public boolean insertCoin(int cents) {
        if (state != VendState.IDLE && state != VendState.HAS_CREDIT) {
            return false;
        }
        if (cents != 25 && cents != 50 && cents != 100) {
            return false;
        }
        credit += cents;
        state = VendState.HAS_CREDIT;
        return true;
    }

    public boolean select() {
        if (state != VendState.HAS_CREDIT || credit < PRICE) {
            return false;
        }
        state = VendState.DISPENSING;
        return true;
    }

    public int dispense() {
        if (state != VendState.DISPENSING) {
            return -1;
        }
        int change = credit - PRICE;
        credit = 0;
        stock--;
        state = stock == 0 ? VendState.SOLD_OUT : VendState.IDLE;
        return change;
    }

    public int refund() {
        if (state != VendState.HAS_CREDIT) {
            return 0;
        }
        int back = credit;
        credit = 0;
        state = VendState.IDLE;
        return back;
    }
}
